import sys

def read_input():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    current = [list(data[i + 2]) for i in range(n)]
    desired = [list(data[i + 2 + n]) for i in range(n)]
    return n, m, current, desired

def find_2x2_square(current, n, m):
    for i in range(n - 1):
        for j in range(m - 1):
            if current[i][j] == 'L' and current[i][j + 1] == 'R' and current[i + 1][j] == 'U' and current[i + 1][j + 1] == 'D':
                return i, j
            if current[i][j] == 'U' and current[i][j + 1] == 'D' and current[i + 1][j] == 'L' and current[i + 1][j + 1] == 'R':
                return i, j
    return None

def rotate_2x2_square(current, i, j):
    current[i][j], current[i][j + 1], current[i + 1][j], current[i + 1][j + 1] = 'U', 'D', 'L', 'R'

def main():
    n, m, current, desired = read_input()
    operations = []

    while current != desired:
        found = False
        for i in range(n - 1):
            for j in range(m - 1):
                if current[i][j] != desired[i][j]:
                    square = find_2x2_square(current, n, m)
                    if square:
                        x, y = square
                        rotate_2x2_square(current, x, y)
                        operations.append((x + 1, y + 1))
                        found = True
                        break
            if found:
                break
        if not found:
            print(-1)
            return

    print(len(operations))
    for op in operations:
        print(op[0], op[1])

if __name__ == "__main__":
    main()
